-- THQ ERP v5.2 GST & Compliance
-- Migration 231: distinguish outward recipient RCM from inward THQ RCM liability.
-- No business transaction/journal data changes.
begin;
do $hotfix$
declare v_oid oid;v_def text;
begin select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='gst_document_quote_v520' and pg_get_function_identity_arguments(p.oid)='p_tenant_id uuid, p_document_kind text, p_location_id uuid, p_party_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric, p_round_off numeric';if v_oid is null then raise exception 'gst_document_quote_v520 not found';end if;select pg_get_functiondef(v_oid) into v_def;if position('has_service boolean:=false;' in v_def)=0 then raise exception 'Expected GST engine declaration pattern not found';end if;if position($pat$'rcm_tax_amount',round(rcm_tax,2),'line_total'$pat$ in v_def)=0 then raise exception 'Expected GST RCM line payload pattern not found';end if;if position($pat$'rcm_tax_payable_total',round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2)$pat$ in v_def)=0 then raise exception 'Expected GST RCM totals pattern not found';end if;v_def:=replace(v_def,'has_service boolean:=false;','has_service boolean:=false;has_rcm boolean:=false;');v_def:=replace(v_def,$pat$if supply_kind='service' then has_service:=true;end if;$pat$,$rep$if supply_kind='service' then has_service:=true;end if;if rcm then has_rcm:=true;end if;$rep$);v_def:=replace(v_def,$pat$'rcm_tax_amount',round(rcm_tax,2),'line_total'$pat$,$rep$'rcm_tax_amount',round(rcm_tax,2),'rcm_liability_party',case when rcm then case when kind='sale' then 'recipient' else 'thq' end else null end,'line_total'$rep$);v_def:=replace(v_def,$pat$'rcm_tax_payable_total',round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2),'government_tax_total'$pat$,$rep$'rcm_tax_payable_total',round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2),'thq_rcm_tax_payable_total',case when kind='purchase' then round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2) else 0 end,'recipient_rcm_tax_payable_total',case when kind='sale' then round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2) else 0 end,'government_tax_total'$rep$);v_def:=replace(v_def,$pat$if has_service and p_place_of_supply_code is null$pat$,$rep$if has_rcm and kind='sale' and (party.id is null or party.registration_type not in('registered','composition','sez')) then errors:=array_append(errors,'Outward reverse-charge supply requires a normalized registered recipient GST profile');end if;if has_service and p_place_of_supply_code is null$rep$);execute v_def;end $hotfix$;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(231,'5.2.0-foundation','GST RCM Liability Scope','Separates outward recipient RCM from inward THQ RCM liability in the central GST engine, annotates line liability party, adds THQ/recipient RCM totals, and requires a normalized registered recipient for outward RCM.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;
commit;